# Provenance: 3rd analysis of 2026-11-15 (section 10 of ACHADOS). Read-only. POST HOC.
# Input: res_b3_lasso_adaptativo.csv (generated by b3_adaptive_lasso.py).
import sys

import numpy as np
import pandas as pd
from scipy.stats import wilcoxon

D = pd.read_csv(sys.argv[1])
pd.set_option("display.width", 250)
pd.set_option("display.max_rows", 200)
D["fam"] = D.cenario.str.replace("benchmark_|real_", "", regex=True).str.split("_").str[:2].str.join("_")
D.loc[D.cenario.str.contains("causal_chamber"), "fam"] = "causal_chamber"
C = D[D.fam == "causal_chamber"].copy()
C["tipo"] = np.where(C.cenario.str.contains("random_walk"), "random walk",
                     np.where(C.cenario.str.contains("hatch_mix_fast"), "fast hatch",
                              np.where(C.cenario.str.contains("hatch_mix_slow"), "slow hatch", "light tunnel")))
cols = ["atual_f1", "C_f1", "AL_f1", "CA_f1", "f1_varlingam", "atual_n", "AL_n", "atual_prec", "atual_rev", "AL_prec", "AL_rev"]
print("== Causal Chambers, 20 scenarios")
print("   AL = VAR + adaptive lasso alone; CA = Stage 6 intersect AL; C = Stage 6 intersect simple lasso")
print(C.groupby(["conj", "grupo"]).agg(cen=("n", "size"), **{c: (c, "mean") for c in cols}).round(3).to_string())
print(C.groupby("tipo").agg(cen=("n", "size"), **{c: (c, "mean") for c in cols}).round(3).to_string())
print("mean of the 20:", C[cols].mean().round(3).to_dict())
for a in ["AL_f1", "CA_f1", "atual_f1"]:
    d = C[a] - C.f1_varlingam
    print("  %s - VARLiNGAM: %+.3f (%d/%d) p=%.3g" % (a, d.mean(), (d > 0).sum(), (d < 0).sum(), wilcoxon(d).pvalue))
d = C.CA_f1 - C.atual_f1
print("  CA - current: %+.3f (%d/%d) p=%.3g" % (d.mean(), (d > 0).sum(), (d < 0).sum(), wilcoxon(d).pvalue))
print("  AL hits that were not pipeline candidates:", int(C.al_tp_fora_dos_candidatos.sum()), "of", int(C.AL_tp.sum()),
      "| candidates cover", int(C.cand_tp.sum()), "of", int(C.n_gt.sum()), "true edges")
print(C[["conj", "cenario", "grupo", "n_gt", "atual_f1", "C_f1", "AL_f1", "CA_f1", "f1_varlingam"]]
      .assign(cenario=lambda x: x.cenario.str[-26:]).round(3).to_string(index=False))
print("\n== Other families with estimable OLS, development sets")
R = D[(D.fam != "causal_chamber") & (D.conj != "cc9_visto")]
print(R.groupby(["grupo", "fam"]).agg(cen=("n", "size"), atual=("atual_f1", "mean"), C=("C_f1", "mean"), AL=("AL_f1", "mean"),
                                      CA=("CA_f1", "mean"), varl=("f1_varlingam", "mean"), atual_mcc=("atual_mcc", "mean"),
                                      AL_mcc=("AL_mcc", "mean")).round(3).to_string())
print("total outside Causal Chambers:", len(R), "scenarios | current", R.atual_f1.mean().round(3), "| AL", R.AL_f1.mean().round(3),
      "| CA", R.CA_f1.mean().round(3))
print(R.groupby("grupo").agg(cen=("n", "size"), atual=("atual_f1", "mean"), AL=("AL_f1", "mean"), CA=("CA_f1", "mean")).round(3).to_string())
